UPDATE PAYMENT
SET PAYMENT_STATUS = 'CANCELED', CANCELED_AT = #{canceledAt, jdbcType=VARCHAR}, CANCEL_REASON = #{cancelReason, jdbcType=VARCHAR}
WHERE PAYMENT_NO = #{paymentNo, jdbcType=NUMERIC}
AND PAYMENT_ID = #{paymentId, jdbcType=VARCHAR}
AND PAYMENT_STATUS = 'PAID'

UPDATE PAYMENT
   SET CANCELED_AMOUNT = #{canceledAmount, jdbcType=NUMERIC},
       PAYMENT_STATUS = #{paymentStatus, jdbcType=VARCHAR},
       CANCELED_AT = #{canceledAt, jdbcType=VARCHAR},
       CANCEL_REASON = #{cancelReason, jdbcType=VARCHAR}
 WHERE PAYMENT_NO = #{paymentNo, jdbcType=NUMERIC}
   AND PAYMENT_ID = #{paymentId, jdbcType=VARCHAR}
   AND PAYMENT_STATUS IN ('PAID', 'PARTIAL_CANCELED')
